const fs = require('fs');
const path = require('path');
const crypto = require('crypto');
const { badRequest } = require('../errors');

/**
 * Private media storage for message attachments (never publicly served; downloads go through an
 * authenticated API route that re-checks conversation access).
 *
 * Drivers share one contract:
 *   put({ companyId, buffer, ext, contentType }) → { key, size }
 *   get(key)                                      → Buffer
 *   remove(key)                                   → void
 *
 * Keys are generated by the server only: companies/<companyId>/media/<yyyy-mm>/<uuid>.<ext>.
 * Nothing user-supplied (file names, paths) ever becomes part of a key.
 *
 *   MEDIA_DRIVER=local  files under MEDIA_DIR (default: <uploads dir>-media, outside the public folder)
 *   MEDIA_DRIVER=s3     any S3-compatible service (AWS S3, Cloudflare R2, Backblaze B2, MinIO, …)
 */
const KEY = /^companies\/[0-9a-f-]{36}\/media\/\d{4}-\d{2}\/[0-9a-f-]{36}\.[a-z0-9]{1,5}$/;
const UUID = /^[0-9a-f-]{36}$/;

function newKey(companyId, ext) {
  if (!UUID.test(String(companyId))) throw new Error('invalid company id for media key');
  if (!/^[a-z0-9]{1,5}$/.test(String(ext))) throw new Error('invalid media extension');
  const month = new Date().toISOString().slice(0, 7);
  return `companies/${companyId}/media/${month}/${crypto.randomUUID()}.${ext}`;
}

function assertKey(key) {
  if (!KEY.test(String(key))) throw new Error('invalid media key');
  return key;
}

function createLocalDriver({ dir }) {
  const root = path.resolve(dir);
  fs.mkdirSync(root, { recursive: true });
  const full = key => {
    const p = path.resolve(root, assertKey(key));
    if (!p.startsWith(root + path.sep)) throw new Error('invalid media key');
    return p;
  };
  return {
    driver: 'local',
    async put({ companyId, buffer, ext }) {
      const key = newKey(companyId, ext);
      const p = full(key);
      await fs.promises.mkdir(path.dirname(p), { recursive: true });
      await fs.promises.writeFile(p, buffer, { flag: 'wx', mode: 0o600 });
      return { key, size: buffer.length };
    },
    async get(key) { return fs.promises.readFile(full(key)); },
    async remove(key) { await fs.promises.rm(full(key), { force: true }); },
    async health() { try { await fs.promises.access(root, fs.constants.W_OK); return true; } catch { return false; } }
  };
}

function createS3Driver({ bucket, region, endpoint, accessKeyId, secretAccessKey, forcePathStyle = true, client }) {
  if (!bucket) throw new Error('MEDIA_S3_BUCKET is required for the s3 media driver');
  const { S3Client, PutObjectCommand, GetObjectCommand, DeleteObjectCommand, HeadBucketCommand } = require('@aws-sdk/client-s3');
  const s3 = client || new S3Client({
    region: region || 'auto',
    endpoint: endpoint || undefined,
    forcePathStyle,
    credentials: accessKeyId ? { accessKeyId, secretAccessKey } : undefined,
    // Several S3-compatible services do not support the newer default checksum headers.
    requestChecksumCalculation: 'WHEN_REQUIRED',
    responseChecksumValidation: 'WHEN_REQUIRED'
  });
  return {
    driver: 's3',
    async put({ companyId, buffer, ext, contentType }) {
      const key = newKey(companyId, ext);
      await s3.send(new PutObjectCommand({
        Bucket: bucket, Key: key, Body: buffer, ContentType: contentType || 'application/octet-stream'
      }));
      return { key, size: buffer.length };
    },
    async get(key) {
      const out = await s3.send(new GetObjectCommand({ Bucket: bucket, Key: assertKey(key) }));
      return Buffer.from(await out.Body.transformToByteArray());
    },
    async remove(key) { await s3.send(new DeleteObjectCommand({ Bucket: bucket, Key: assertKey(key) })); },
    async health() { try { await s3.send(new HeadBucketCommand({ Bucket: bucket })); return true; } catch { return false; } }
  };
}

/** Default private media directory: a sibling of the public uploads folder (never under it). */
const defaultMediaDir = uploadsDir => path.join(path.dirname(path.resolve(uploadsDir)), `${path.basename(path.resolve(uploadsDir))}-media`);

function createMediaStorage(config) {
  const media = config.media || {};
  const driver = media.driver || 'local';
  if (driver === 's3') return createS3Driver(media.s3 || {});
  if (driver === 'local') return createLocalDriver({ dir: media.dir || defaultMediaDir(config.uploadsDir) });
  throw new Error('MEDIA_DRIVER must be local or s3');
}

// ---------------------------------------------------------------- content detection
/** Recognised by magic bytes. `inline` types may be shown in the browser; all others download. */
const TYPES = [
  { ext: 'png', mime: 'image/png', kind: 'image', inline: true, test: b => b.length > 8 && b.subarray(0, 8).equals(Buffer.from([0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a])) },
  { ext: 'jpg', mime: 'image/jpeg', kind: 'image', inline: true, test: b => b.length > 3 && b[0] === 0xff && b[1] === 0xd8 && b[2] === 0xff },
  { ext: 'gif', mime: 'image/gif', kind: 'image', inline: true, test: b => b.subarray(0, 4).toString('ascii') === 'GIF8' },
  { ext: 'webp', mime: 'image/webp', kind: 'image', inline: true, test: b => b.subarray(0, 4).toString('ascii') === 'RIFF' && b.subarray(8, 12).toString('ascii') === 'WEBP' },
  { ext: 'pdf', mime: 'application/pdf', kind: 'file', test: b => b.subarray(0, 5).toString('ascii') === '%PDF-' },
  { ext: 'ogg', mime: 'audio/ogg', kind: 'audio', test: b => b.subarray(0, 4).toString('ascii') === 'OggS' },
  { ext: 'mp3', mime: 'audio/mpeg', kind: 'audio', test: b => b.subarray(0, 3).toString('ascii') === 'ID3' || (b[0] === 0xff && (b[1] & 0xe0) === 0xe0) },
  { ext: 'mp4', mime: 'video/mp4', kind: 'video', test: b => b.length > 12 && b.subarray(4, 8).toString('ascii') === 'ftyp' },
  { ext: 'zip', mime: 'application/zip', kind: 'file', test: b => b.length > 4 && b[0] === 0x50 && b[1] === 0x4b && b[2] === 0x03 && b[3] === 0x04 }
];
const OFFICE = { docx: 'application/vnd.openxmlformats-officedocument.wordprocessingml.document', xlsx: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet', pptx: 'application/vnd.openxmlformats-officedocument.presentationml.presentation' };

/** Clean a display file name (kept only as metadata, never used as a path). */
function safeName(name, fallback) {
  const base = String(name || '').split(/[\\/]/).pop().replace(/[\u0000-\u001f\u007f"<>|*?:]/g, '').trim().slice(0, 120);
  return base || fallback;
}

/**
 * Identify content by its bytes. Office files are ZIP containers: the declared extension is
 * trusted only to pick between docx/xlsx/pptx inside a verified ZIP.
 * Returns null for unrecognised content.
 */
function detect(buffer, originalName) {
  const t = TYPES.find(x => x.test(buffer));
  if (!t) return null;
  if (t.ext === 'zip') {
    const declared = String(originalName || '').toLowerCase().split('.').pop();
    if (OFFICE[declared]) return { ext: declared, mime: OFFICE[declared], kind: 'file', inline: false };
  }
  return { ext: t.ext, mime: t.mime, kind: t.kind, inline: Boolean(t.inline) };
}

/** Validate an uploaded file for sending. Throws a translated 400 for unsupported content. */
function inspectUpload(file, { maxBytes }) {
  if (!file || !file.buffer || !file.buffer.length) throw badRequest('media.empty', 'The file is empty');
  if (file.buffer.length > maxBytes) throw badRequest('media.too_large', 'The file is too large');
  const type = detect(file.buffer, file.originalname);
  if (!type) throw badRequest('media.unsupported_type', 'This file type is not supported');
  return { ...type, name: safeName(file.originalname, `file.${type.ext}`), size: file.buffer.length };
}

module.exports = { createMediaStorage, createLocalDriver, createS3Driver, detect, inspectUpload, safeName, defaultMediaDir, newKey };
